use vstd::prelude::*;

verus! {

// A small helper predicate for “zero complex number”.
spec fn is_zero_complex(z: (f64, f64)) -> bool {
    z.0 == 0.0 && z.1 == 0.0
}

fn imag(val: Vec<(f64, f64)>) -> (out: Vec<f64>)
    ensures
        // Same length
        out.len() == val.len(),
        // Pointwise: output[i] is the imaginary part of input[i]
        forall|i: int| 0 <= i < val.len() ==> out[i] == val[i].1,
        // If imaginary part is 0.0, output is 0.0
        forall|i: int| 0 <= i < val.len() ==> (val[i].1 == 0.0 ==> out[i] == 0.0),
        // If input is not the zero complex number, output equals imaginary part (redundant but required)
        forall|i: int| 0 <= i < val.len() ==> (!is_zero_complex(val[i]) ==> out[i] == val[i].1),
{
    let mut out: Vec<f64> = Vec::new();
    let mut i: usize = 0;

    while i < val.len()
        invariant
            out.len() == i,
            i <= val.len(),
            // Already-built prefix is correct
            forall|j: int| 0 <= j < i ==> out[j] == val[j].1,
        decreases val.len() - i,
    {
        let im: f64 = val[i].1;
        out.push(im);
        i = i + 1;
    }

    out
}

} // verus!

